# Single source of truth. Each row: the need, then the service on each cloud.
# Use ' / ' to list alternatives. 'n/a' = no direct equivalent (quiz skips it).
title: "Tri-cloud service map (AWS / Azure / Google Cloud)"
intro: "Service models: IaaS = you manage OS and up; PaaS = you manage code and data; SaaS = you manage data and users; serverless = no servers to manage, pay per use."
sections:
  Compute:
    - {need: "Virtual machines (IaaS)", aws: "Amazon EC2", azure: "Azure Virtual Machines", gcp: "Compute Engine"}
    - {need: "Managed Kubernetes", aws: "Amazon EKS", azure: "Azure Kubernetes Service (AKS)", gcp: "Google Kubernetes Engine (GKE)"}
    - {need: "Serverless functions", aws: "AWS Lambda", azure: "Azure Functions", gcp: "Cloud Run functions"}
    - {need: "Serverless containers", aws: "AWS Fargate / AWS App Runner", azure: "Azure Container Apps", gcp: "Cloud Run"}
    - {need: "Web app PaaS", aws: "AWS Elastic Beanstalk", azure: "Azure App Service", gcp: "App Engine"}
  Storage:
    - {need: "Object storage", aws: "Amazon S3", azure: "Azure Blob Storage", gcp: "Cloud Storage"}
    - {need: "Block storage for VMs", aws: "Amazon EBS", azure: "Azure Managed Disks", gcp: "Persistent Disk / Hyperdisk"}
    - {need: "Managed file shares", aws: "Amazon EFS", azure: "Azure Files", gcp: "Filestore"}
    - {need: "Archive tier", aws: "S3 Glacier Deep Archive", azure: "Blob Archive tier", gcp: "Archive storage class"}
  Database:
    - {need: "Managed relational", aws: "Amazon RDS / Amazon Aurora", azure: "Azure SQL Database / Azure Database for PostgreSQL", gcp: "Cloud SQL / AlloyDB"}
    - {need: "Globally distributed relational", aws: "Amazon Aurora DSQL", azure: "n/a", gcp: "Spanner"}
    - {need: "NoSQL key-value / document", aws: "Amazon DynamoDB", azure: "Azure Cosmos DB", gcp: "Firestore"}
    - {need: "Data warehouse", aws: "Amazon Redshift", azure: "Azure Synapse Analytics", gcp: "BigQuery"}
  Networking:
    - {need: "Private network", aws: "Amazon VPC", azure: "Azure Virtual Network (VNet)", gcp: "VPC network"}
    - {need: "Load balancing", aws: "Elastic Load Balancing (ALB, NLB)", azure: "Azure Load Balancer / Application Gateway", gcp: "Cloud Load Balancing"}
    - {need: "DNS", aws: "Amazon Route 53", azure: "Azure DNS", gcp: "Cloud DNS"}
    - {need: "CDN", aws: "Amazon CloudFront", azure: "Azure Front Door", gcp: "Cloud CDN"}
    - {need: "Dedicated private link to on-premises", aws: "AWS Direct Connect", azure: "Azure ExpressRoute", gcp: "Cloud Interconnect"}
    - {need: "Site-to-site VPN", aws: "AWS Site-to-Site VPN", azure: "Azure VPN Gateway", gcp: "Cloud VPN"}
  Global infrastructure:
    - {need: "Isolated datacentre group in a region", aws: "Availability Zone", azure: "Availability zone", gcp: "Zone"}
    - {need: "Fixed partner region for DR", aws: "n/a", azure: "Region pairs", gcp: "n/a"}
    - {need: "India regions used here", aws: "ap-south-1 (Mumbai)", azure: "centralindia (Pune)", gcp: "asia-south1 (Mumbai)"}
  Pricing models:
    - {need: "Pay per second or hour, no commitment", aws: "On-Demand Instances", azure: "Pay-as-you-go", gcp: "On-demand pricing"}
    - {need: "1- or 3-year commitment discount", aws: "Savings Plans / Reserved Instances", azure: "Azure savings plan for compute / Azure Reservations", gcp: "Committed use discounts"}
    - {need: "Spare capacity, can be reclaimed", aws: "Spot Instances", azure: "Azure Spot Virtual Machines", gcp: "Spot VMs"}
    - {need: "Automatic discount for steady usage", aws: "n/a", azure: "n/a", gcp: "Sustained use discounts"}
traps:
  - "Shared responsibility: the provider secures the cloud (facilities, hardware, hypervisor). You secure what you put in it. Data, identities and access are always yours."
  - "IaaS -> PaaS -> SaaS moves more work to the provider. On IaaS you patch the guest OS; on PaaS you do not."
  - "Google Cloud VPC network is global with regional subnets. AWS VPC and Azure VNet are regional."
  - "An AWS subnet sits in one Availability Zone. Azure and Google Cloud subnets span the zones of a region."
  - "Azure region pairs (e.g. Central India and South India) drive geo-redundant storage and staged platform updates. Some newer regions have no pair."
  - "Edge locations / points of presence serve CDN and DNS traffic. You cannot run your VMs there."
  - "Spot capacity can be taken back at short notice. Use it only for fault-tolerant, interruptible work."

# Inputs shared by all three providers in main.tf

variable "prefix" {
  description = "Lowercase letters and digits only (Azure storage account rule)"
  type        = string
  default     = "svcmap"
}

variable "aws_region" {
  description = "AWS Region code"
  type        = string
  default     = "ap-south-1" # Mumbai
}

variable "azure_location" {
  description = "Azure region name"
  type        = string
  default     = "centralindia" # Pune; paired with South India
}

variable "azure_subscription_id" {
  description = "Azure subscription ID (required by azurerm 4.x)"
  type        = string
}

variable "gcp_project" {
  description = "Google Cloud project ID"
  type        = string
}

variable "gcp_region" {
  description = "Google Cloud region"
  type        = string
  default     = "asia-south1" # Mumbai
}

# One private object-storage bucket on each cloud: S3 / Blob Storage / Cloud Storage
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws     = { source = "hashicorp/aws", version = ">= 5.0" }
    azurerm = { source = "hashicorp/azurerm", version = "~> 4.9" }
    google  = { source = "hashicorp/google", version = ">= 6.0" }
    random  = { source = "hashicorp/random", version = "~> 3.6" }
  }
}

provider "aws" { region = var.aws_region }
provider "azurerm" {
  features {}
  subscription_id = var.azure_subscription_id
}
provider "google" {
  project = var.gcp_project
  region  = var.gcp_region
}

# Bucket and storage account names must be globally unique
resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

# AWS: bucket is a top-level resource; Region comes from the provider
resource "aws_s3_bucket" "map" {
  bucket        = "${var.prefix}-${random_string.suffix.result}"
  force_destroy = true
}
resource "aws_s3_bucket_public_access_block" "map" {
  bucket                  = aws_s3_bucket.map.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Azure: resource group -> storage account -> container
resource "azurerm_resource_group" "map" {
  name     = "rg-${var.prefix}"
  location = var.azure_location
}
resource "azurerm_storage_account" "map" {
  name                            = "${var.prefix}${random_string.suffix.result}"
  resource_group_name             = azurerm_resource_group.map.name
  location                        = azurerm_resource_group.map.location
  account_tier                    = "Standard"
  account_replication_type        = "ZRS" # copies across availability zones in the region
  min_tls_version                 = "TLS1_2"
  allow_nested_items_to_be_public = false
}
resource "azurerm_storage_container" "map" {
  name                  = "service-map"
  storage_account_id    = azurerm_storage_account.map.id
  container_access_type = "private"
}

# Google Cloud: bucket location is a region (could also be dual- or multi-region)
resource "google_storage_bucket" "map" {
  name                        = "${var.prefix}-${random_string.suffix.result}"
  location                    = upper(var.gcp_region)
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
  force_destroy               = true
}

output "buckets" {
  value = {
    aws   = aws_s3_bucket.map.bucket
    azure = "${azurerm_storage_account.map.name}/${azurerm_storage_container.map.name}"
    gcp   = google_storage_bucket.map.name
  }
}

