# Non-functional requirements as numbers, plus the six-pillar review findings.
service: orders-api
slo:
  availability_percent: 99.9      # SLI = successful HTTP requests / all requests
  window_days: 30                 # rolling window -> error budget 43.2 min
  latency_p99_ms: 300
sla_percent: 99.5                 # customer promise, kept looser than the SLO

recovery_targets:                 # minutes
  zone_failure:   {rto: 5,   rpo: 0}
  region_failure: {rto: 240, rpo: 15}

architectures:
  current:
    components:                   # in series: a request needs all of them
      - {name: alb,          availability: 99.99}
      - {name: ec2_instance, availability: 99.5, copies: 2}   # 2 AZs, parallel
      - {name: rds_single_az, availability: 99.5}
    recovery:
      zone_failure:   {rto: 120, rpo: 5}   # restore from PITR into another AZ
      region_failure: null                 # backups stay in ap-south-1: no DR
  proposed:
    components:
      - {name: alb,          availability: 99.99}
      - {name: ec2_instance, availability: 99.5, copies: 2}
      - {name: rds_multi_az, availability: 99.95}             # ADR-0001
    recovery:
      zone_failure:   {rto: 2,   rpo: 0}    # synchronous standby failover
      region_failure: {rto: 180, rpo: 10}   # ADR-0002, estimate: verify in drill

findings:
  - {pillar: Reliability, risk: high, adr: ADR-0001,
     finding: "Single-AZ database is a single point of failure"}
  - {pillar: Reliability, risk: high, adr: ADR-0002,
     finding: "No copy of data outside ap-south-1; region RTO/RPO cannot be met"}
  - {pillar: Security, risk: high, adr: ADR-0003,
     finding: "DB master password stored as plain text in EC2 user data"}
  - {pillar: Operational Excellence, risk: medium, adr: null,
     finding: "No alarm on error-budget burn rate"}
  - {pillar: Performance Efficiency, risk: low, adr: null,
     finding: "p99 latency not measured at the ALB"}
  - {pillar: Cost Optimization, risk: medium, adr: null,
     finding: "No cost allocation tags; on-demand only"}
  - {pillar: Sustainability, risk: low, adr: null,
     finding: "x86 instances; Graviton could cut energy and cost"}

# Implements ADR-0001 (Multi-AZ), ADR-0002 (cross-region backups), ADR-0003 (managed secret).
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" {
  region = "ap-south-1"                       # primary: Mumbai
  default_tags { tags = { app = "orders-api", cost-centre = "orders" } }  # FinOps tags
}

provider "aws" {
  alias  = "dr"
  region = "ap-south-2"                       # DR: Hyderabad
  default_tags { tags = { app = "orders-api", cost-centre = "orders" } }
}

variable "db_subnet_group_name" { type = string }
variable "db_security_group_ids" { type = list(string) }

resource "aws_db_instance" "orders" {
  identifier                  = "orders-db"
  engine                      = "postgres"
  engine_version              = "16"
  instance_class              = "db.m7g.large"  # Graviton
  allocated_storage           = 50
  storage_encrypted           = true          # required by the security baseline
  username                    = "orders_admin"
  manage_master_user_password = true          # ADR-0003: secret in Secrets Manager
  multi_az                    = true          # ADR-0001: synchronous standby in a 2nd AZ
  backup_retention_period     = 7             # enables PITR (needed for ADR-0002)
  copy_tags_to_snapshot       = true
  deletion_protection         = true
  db_subnet_group_name        = var.db_subnet_group_name
  vpc_security_group_ids      = var.db_security_group_ids
  skip_final_snapshot         = false
  final_snapshot_identifier   = "orders-db-final"
}

# ADR-0002: encrypted backups need a KMS key that lives in the DR region.
resource "aws_kms_key" "dr_backups" {
  provider                = aws.dr
  description             = "orders-db replicated automated backups"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_db_instance_automated_backups_replication" "orders_dr" {
  provider               = aws.dr               # created in the destination region
  source_db_instance_arn = aws_db_instance.orders.arn
  kms_key_id             = aws_kms_key.dr_backups.arn
  retention_period       = 7                  # PITR window in ap-south-2
}

output "db_secret_arn" {
  # Grant the app role only secretsmanager:GetSecretValue on this ARN.
  value = aws_db_instance.orders.master_user_secret[0].secret_arn
}

