terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  region = "ap-south-1" # Mumbai; run with management-account credentials
}

variable "email_prefix" { type = string }
variable "email_domain" { type = string }

# The organisation must already exist with all features enabled (needed for SCPs)
data "aws_organizations_organization" "org" {}

locals {
  root_id = data.aws_organizations_organization.org.roots[0].id
}

# OUs follow the AWS multi-account guidance: Security, Infrastructure, Workloads
resource "aws_organizations_organizational_unit" "security" {
  name      = "Security"
  parent_id = local.root_id
}

resource "aws_organizations_organizational_unit" "infrastructure" {
  name      = "Infrastructure"
  parent_id = local.root_id
}

resource "aws_organizations_organizational_unit" "workloads" {
  name      = "Workloads"
  parent_id = local.root_id
}

locals {
  accounts = {
    security        = aws_organizations_organizational_unit.security.id
    shared-services = aws_organizations_organizational_unit.infrastructure.id
    dev             = aws_organizations_organizational_unit.workloads.id
    prod            = aws_organizations_organizational_unit.workloads.id
  }
}

# One member account per purpose = hard blast-radius boundary
resource "aws_organizations_account" "this" {
  for_each          = local.accounts
  name              = each.key
  email             = "${var.email_prefix}+${each.key}@${var.email_domain}" # must be unique
  parent_id         = each.value
  role_name         = "OrganizationAccountAccessRole" # admin role trusted by management account
  close_on_deletion = false
}

output "account_ids" {
  value = { for k, a in aws_organizations_account.this : k => a.id }
}

# SCP 1: nobody except the break-glass role may stop or change audit logging
resource "aws_organizations_policy" "protect_logging" {
  name = "deny-logging-tampering"
  type = "SERVICE_CONTROL_POLICY"
  content = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "DenyAuditLogChanges"
      Effect = "Deny"
      Action = [
        "cloudtrail:StopLogging", "cloudtrail:DeleteTrail", "cloudtrail:UpdateTrail",
        "cloudtrail:PutEventSelectors", "config:StopConfigurationRecorder",
        "config:DeleteConfigurationRecorder", "config:DeleteDeliveryChannel"
      ]
      Resource = "*"
      Condition = { ArnNotLike = { "aws:PrincipalArn" = "arn:aws:iam::*:role/OrganizationAccountAccessRole" } }
    }]
  })
}

# SCP 2: deny regional actions outside the two Indian regions; global services are exempt
resource "aws_organizations_policy" "region_guard" {
  name = "deny-unapproved-regions"
  type = "SERVICE_CONTROL_POLICY"
  content = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "DenyOutsideIndia"
      Effect = "Deny"
      NotAction = [
        "iam:*", "organizations:*", "sts:*", "route53:*", "route53domains:*",
        "cloudfront:*", "globalaccelerator:*", "waf:*", "wafv2:*", "shield:*",
        "budgets:*", "ce:*", "cur:*", "health:*", "support:*", "trustedadvisor:*"
      ]
      Resource = "*"
      Condition = {
        StringNotEquals = { "aws:RequestedRegion" = ["ap-south-1", "ap-south-2"] }
        ArnNotLike      = { "aws:PrincipalArn" = "arn:aws:iam::*:role/OrganizationAccountAccessRole" }
      }
    }]
  })
}

# Attach the logging SCP at the root so it covers every OU and member account
resource "aws_organizations_policy_attachment" "logging_root" {
  policy_id = aws_organizations_policy.protect_logging.id
  target_id = local.root_id
}

# Attach the region SCP to the OUs that run workloads and shared services
resource "aws_organizations_policy_attachment" "region_ous" {
  for_each = {
    workloads      = aws_organizations_organizational_unit.workloads.id
    infrastructure = aws_organizations_organizational_unit.infrastructure.id
  }
  policy_id = aws_organizations_policy.region_guard.id
  target_id = each.value
}

terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

variable "dev_account_id" { type = string }
variable "trusted_account_id" { type = string } # account whose users may assume Developer

provider "aws" {
  region = "ap-south-1"
  assume_role { role_arn = "arn:aws:iam::${var.dev_account_id}:role/OrganizationAccountAccessRole" }
}

locals {
  boundary_arn = "arn:aws:iam::${var.dev_account_id}:policy/DeveloperBoundary"
}

# Permissions boundary: the maximum any developer-created principal can ever have
resource "aws_iam_policy" "boundary" {
  name = "DeveloperBoundary"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "AllowAppServices", Effect = "Allow", Resource = "*",
        Action = ["ec2:*", "s3:*", "lambda:*", "logs:*", "cloudwatch:*", "iam:PassRole", "iam:Get*", "iam:List*"] },
      # New roles must carry this same boundary, which blocks privilege escalation
      { Sid = "CreateRoleOnlyWithBoundary", Effect = "Allow", Resource = "*",
        Action = ["iam:CreateRole", "iam:AttachRolePolicy", "iam:PutRolePolicy"],
        Condition = { StringEquals = { "iam:PermissionsBoundary" = local.boundary_arn } } },
      { Sid = "ProtectBoundary", Effect = "Deny", Resource = local.boundary_arn,
        Action = ["iam:DeletePolicy", "iam:CreatePolicyVersion", "iam:SetDefaultPolicyVersion"] },
      { Sid = "NoBoundaryRemoval", Effect = "Deny", Resource = "*",
        Action = ["iam:DeleteRolePermissionsBoundary"] }
    ]
  })
}

# Short-lived, MFA-only role: humans assume it; no long-term access keys
resource "aws_iam_role" "developer" {
  name                 = "Developer"
  max_session_duration = 3600
  permissions_boundary = aws_iam_policy.boundary.arn
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow", Action = "sts:AssumeRole"
      Principal = { AWS = "arn:aws:iam::${var.trusted_account_id}:root" }
      Condition = { Bool = { "aws:MultiFactorAuthPresent" = "true" } }
    }]
  })
}

# Identity policy is broad; the boundary and SCPs cut it down to the safe intersection
resource "aws_iam_role_policy_attachment" "poweruser" {
  role       = aws_iam_role.developer.name
  policy_arn = "arn:aws:iam::aws:policy/PowerUserAccess"
}

terraform {
  required_providers {
    azurerm = { source = "hashicorp/azurerm", version = "~> 4.0" }
  }
}

provider "azurerm" {
  features {}
}

variable "tenant_root_mg_id" { type = string } # tenant root group = tenant ID

locals {
  root_id = "/providers/Microsoft.Management/managementGroups/${var.tenant_root_mg_id}"
}

# Hierarchy: Platform (security, shared) and Landing zones (dev, prod)
resource "azurerm_management_group" "platform" {
  display_name               = "Platform"
  parent_management_group_id = local.root_id
}

resource "azurerm_management_group" "landingzones" {
  display_name               = "Landing zones"
  parent_management_group_id = local.root_id
}

resource "azurerm_management_group" "child" {
  for_each = {
    mg-security = azurerm_management_group.platform.id
    mg-shared   = azurerm_management_group.platform.id
    mg-dev      = azurerm_management_group.landingzones.id
    mg-prod     = azurerm_management_group.landingzones.id
  }
  name                       = each.key
  display_name               = each.key
  parent_management_group_id = each.value
}

locals {
  allowed = { listOfAllowedLocations = { value = ["centralindia", "southindia"] } }
}

# Built-in policy "Allowed locations" (resources); assigned at a parent and inherited by children
resource "azurerm_management_group_policy_assignment" "allowed_locations" {
  for_each             = { platform = azurerm_management_group.platform.id, lz = azurerm_management_group.landingzones.id }
  name                 = "allowed-loc-${each.key}"
  management_group_id  = each.value
  policy_definition_id = "/providers/Microsoft.Authorization/policyDefinitions/e56962a6-4747-49cd-b67b-bf8b01975c4c"
  parameters           = jsonencode(local.allowed)
}

# Built-in policy "Allowed locations for resource groups"
resource "azurerm_management_group_policy_assignment" "allowed_rg_locations" {
  for_each             = { platform = azurerm_management_group.platform.id, lz = azurerm_management_group.landingzones.id }
  name                 = "allowed-rgloc-${each.key}"
  management_group_id  = each.value
  policy_definition_id = "/providers/Microsoft.Authorization/policyDefinitions/e765b5de-1225-4ba3-bd56-1ac6695af988"
  parameters           = jsonencode(local.allowed)
}

terraform {
  required_providers {
    google = { source = "hashicorp/google", version = "~> 6.0" }
  }
}

provider "google" {}

variable "org_id" { type = string }

# Resource hierarchy: Organization > folders > projects
resource "google_folder" "this" {
  for_each     = toset(["security", "shared-services", "dev", "prod"])
  display_name = each.key
  parent       = "organizations/${var.org_id}"
}

# Region guardrail at the organisation node; every folder and project inherits it
resource "google_org_policy_policy" "locations" {
  name   = "organizations/${var.org_id}/policies/gcp.resourceLocations"
  parent = "organizations/${var.org_id}"
  spec {
    rules {
      values {
        allowed_values = ["in:asia-south1-locations", "in:asia-south2-locations"] # Mumbai, Delhi
      }
    }
  }
}

# Logging guardrail: nobody may exempt principals from audit logging
resource "google_org_policy_policy" "no_audit_exemptions" {
  name   = "organizations/${var.org_id}/policies/iam.disableAuditLoggingExemption"
  parent = "organizations/${var.org_id}"
  spec {
    rules { enforce = "TRUE" }
  }
}

# Least privilege: use attached service accounts, not downloadable keys
resource "google_org_policy_policy" "no_sa_keys" {
