# One region: a Transit Gateway hub plus spoke VPCs with private subnets in two AZs.
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

variable "vpcs" { type = map(object({ cidr = string, edge = bool })) }
variable "internal_cidrs" { type = list(string) } # all cloud + office ranges, reached via the TGW
variable "asn" { type = number }                  # TGW BGP ASN, unique per region

data "aws_availability_zones" "az" { state = "available" }

locals {
  edge    = one([for k, v in var.vpcs : k if v.edge]) # exactly one egress VPC per region
  private = { for p in setproduct(keys(var.vpcs), [0, 1]) : "${p[0]}-${p[1]}" => { vpc = p[0], az = p[1] } }
  subnets = { for v in keys(var.vpcs) : v => [for k, s in aws_subnet.private : s.id if local.private[k].vpc == v] }
}

resource "aws_ec2_transit_gateway" "hub" {
  amazon_side_asn = var.asn # default route table association and propagation stay enabled
  tags            = { Name = "tgw-${local.edge}" }
}

resource "aws_vpc" "this" {
  for_each             = var.vpcs
  cidr_block           = each.value.cidr
  enable_dns_support   = true # needed for private hosted zones and the Resolver
  enable_dns_hostnames = true
  tags                 = { Name = each.key }
}

resource "aws_subnet" "private" {
  for_each          = local.private
  vpc_id            = aws_vpc.this[each.value.vpc].id
  cidr_block        = cidrsubnet(var.vpcs[each.value.vpc].cidr, 2, each.value.az + 1) # /22 quarters 1 and 2
  availability_zone = data.aws_availability_zones.az.names[each.value.az]
  tags              = { Name = "${each.key}-private" }
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each           = var.vpcs
  transit_gateway_id = aws_ec2_transit_gateway.hub.id
  vpc_id             = aws_vpc.this[each.key].id
  subnet_ids         = local.subnets[each.key] # one TGW ENI per AZ
  tags               = { Name = "att-${each.key}" }
}

resource "aws_route_table" "private" {
  for_each = var.vpcs
  vpc_id   = aws_vpc.this[each.key].id
  route { # spokes send internet traffic to the hub; the edge VPC sends it to its NAT
    cidr_block         = "0.0.0.0/0"
    nat_gateway_id     = each.value.edge ? aws_nat_gateway.edge.id : null
    transit_gateway_id = each.value.edge ? null : aws_ec2_transit_gateway.hub.id
  }
  dynamic "route" { # other VPCs, the other region and the office all go via the TGW
    for_each = var.internal_cidrs
    content {
      cidr_block         = route.value
      transit_gateway_id = aws_ec2_transit_gateway.hub.id
    }
  }
  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this] # TGW routes need the attachment first
}

resource "aws_route_table_association" "private" {
  for_each       = local.private
  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.value.vpc].id
}

output "tgw_id" { value = aws_ec2_transit_gateway.hub.id }
output "tgw_route_table_id" { value = aws_ec2_transit_gateway.hub.association_default_route_table_id }
output "vpc_ids" { value = { for k, v in aws_vpc.this : k => v.id } }
output "private_subnet_ids" { value = local.subnets }

# Centralised egress: only the edge VPC has an internet gateway and a NAT gateway.
# Spoke VPCs have no public subnets, so they cannot be reached from the internet.

resource "aws_internet_gateway" "edge" {
  vpc_id = aws_vpc.this[local.edge].id
  tags   = { Name = "igw-${local.edge}" }
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.this[local.edge].id
  cidr_block        = cidrsubnet(var.vpcs[local.edge].cidr, 4, 0) # first /24, inside spare quarter 0
  availability_zone = data.aws_availability_zones.az.names[0]
  tags              = { Name = "${local.edge}-public-a" }
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

# One NAT saves cost for the lab; production needs one NAT per AZ.
resource "aws_nat_gateway" "edge" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  tags          = { Name = "nat-${local.edge}" }
  depends_on    = [aws_internet_gateway.edge]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this[local.edge].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.edge.id
  }
  dynamic "route" { # return path: replies from the NAT go back to spokes via the TGW
    for_each = var.internal_cidrs
    content {
      cidr_block         = route.value
      transit_gateway_id = aws_ec2_transit_gateway.hub.id
    }
  }
  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Default route in the TGW: all internet-bound spoke traffic goes to the edge VPC.
resource "aws_ec2_transit_gateway_route" "default" {
  destination_cidr_block         = "0.0.0.0/0"
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_vpc_attachment.this[local.edge].id
  transit_gateway_route_table_id = aws_ec2_transit_gateway.hub.association_default_route_table_id
}

# Two regional hubs (Mumbai, Hyderabad) joined by Transit Gateway peering.
terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  alias  = "mumbai"
  region = "ap-south-1"
}

provider "aws" {
  alias  = "hyderabad"
  region = "ap-south-2" # opt-in Region: enable it in the account first
}

# All values come from plan.auto.tfvars.json, written by plan/cidr_plan.py
variable "office_cidr" { type = string }
variable "office_public_ip" { type = string }
variable "supernet_mumbai" { type = string }
variable "supernet_hyderabad" { type = string }
variable "vpcs_mumbai" { type = map(object({ cidr = string, edge = bool })) }
variable "vpcs_hyderabad" { type = map(object({ cidr = string, edge = bool })) }

locals {
  internal = ["10.0.0.0/8", var.office_cidr] # one summary covers both regions
}

module "mumbai" {
  source         = "./modules/region"
  providers      = { aws = aws.mumbai }
  vpcs           = var.vpcs_mumbai
  internal_cidrs = local.internal
  asn            = 64512
}

module "hyderabad" {
  source         = "./modules/region"
  providers      = { aws = aws.hyderabad }
  vpcs           = var.vpcs_hyderabad
  internal_cidrs = local.internal
  asn            = 64513
}

data "aws_caller_identity" "me" { provider = aws.mumbai }

resource "aws_ec2_transit_gateway_peering_attachment" "mum_hyd" {
  provider                = aws.mumbai
  transit_gateway_id      = module.mumbai.tgw_id
  peer_transit_gateway_id = module.hyderabad.tgw_id
  peer_region             = "ap-south-2"
  peer_account_id         = data.aws_caller_identity.me.account_id
  tags                    = { Name = "tgw-peer-mum-hyd" }
}

resource "aws_ec2_transit_gateway_peering_attachment_accepter" "hyd" {
  provider                      = aws.hyderabad
  transit_gateway_attachment_id = aws_ec2_transit_gateway_peering_attachment.mum_hyd.id
}

# Peering attachments do not propagate routes, so add static routes on both sides.
resource "aws_ec2_transit_gateway_route" "mum_to_hyd" {
  provider                       = aws.mumbai
  destination_cidr_block         = var.supernet_hyderabad
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_peering_attachment.mum_hyd.id
  transit_gateway_route_table_id = module.mumbai.tgw_route_table_id
  depends_on                     = [aws_ec2_transit_gateway_peering_attachment_accepter.hyd]
}

resource "aws_ec2_transit_gateway_route" "hyd_to_mum" {
  provider                       = aws.hyderabad
  for_each                       = toset([var.supernet_mumbai, var.office_cidr]) # office is reached via Mumbai's VPN
  destination_cidr_block         = each.value
  transit_gateway_attachment_id  = aws_ec2_transit_gateway_peering_attachment_accepter.hyd.id
  transit_gateway_route_table_id = module.hyderabad.tgw_route_table_id
}

# Office connectivity: site-to-site VPN into the Mumbai TGW, plus hybrid DNS.

resource "aws_customer_gateway" "office" {
  provider   = aws.mumbai
  bgp_asn    = 65000 # private ASN of the office router
  ip_address = var.office_public_ip
  type       = "ipsec.1"
  tags       = { Name = "cgw-office" }
}

resource "aws_vpn_connection" "office" {
  provider            = aws.mumbai
  customer_gateway_id = aws_customer_gateway.office.id
  transit_gateway_id  = module.mumbai.tgw_id # VPN terminates on the hub, not on one VPC
  type                = "ipsec.1"
  static_routes_only  = true # lab only; use BGP in production for dynamic routing and failover
  tags                = { Name = "vpn-office" }
}

# With static routing, tell the TGW that the office range lives behind the VPN.
resource "aws_ec2_transit_gateway_route" "office" {
  provider                       = aws.mumbai
  destination_cidr_block         = var.office_cidr
  transit_gateway_attachment_id  = aws_vpn_connection.office.transit_gateway_attachment_id
  transit_gateway_route_table_id = module.mumbai.tgw_route_table_id
}

resource "aws_security_group" "dns" {
  provider = aws.mumbai
  name     = "resolver-inbound"
  vpc_id   = module.mumbai.vpc_ids["mum-shared"]
  dynamic "ingress" { # DNS uses UDP 53, and TCP 53 for large answers
    for_each = ["udp", "tcp"]
    content {
      from_port   = 53
      to_port     = 53
      protocol    = ingress.value
      cidr_blocks = [var.office_cidr]
    }
  }
}

# Office DNS servers forward corp.internal to these two IPs in mum-shared.
resource "aws_route53_resolver_endpoint" "inbound" {
  provider           = aws.mumbai
  name               = "office-inbound"
  direction          = "INBOUND"
  security_group_ids = [aws_security_group.dns.id]
  dynamic "ip_address" {
    for_each = module.mumbai.private_subnet_ids["mum-shared"]
    content { subnet_id = ip_address.value }
  }
}

# Private hosted zone: names resolve only inside the associated VPCs (and via the Resolver).
resource "aws_route53_zone" "corp" {
  provider = aws.mumbai
  name     = "corp.internal"
  dynamic "vpc" {
    for_each = module.mumbai.vpc_ids
    content { vpc_id = vpc.value }
  }
}

# Demo record. In real work, use a CNAME to the RDS endpoint, because RDS IPs can change.
resource "aws_route53_record" "orders_db" {
  provider = aws.mumbai
  zone_id  = aws_route53_zone.corp.zone_id
  name     = "orders-db.corp.internal"
  type     = "A"
  ttl      = 60
  records  = ["10.10.52.25"] # inside mum-prod-data private AZ-a (10.10.52.0/22)
}

output "vpn_tunnel_ips" { value = [aws_vpn_connection.office.tunnel1_address, aws_vpn_connection.office.tunnel2_address] }
output "resolver_ips" { value = [for a in aws_route53_resolver_endpoint.inbound.ip_address : a.ip] }

