terraform {
  required_version = ">= 1.6"
  required_providers {
    aws     = { source = "hashicorp/aws", version = "~> 5.80" }
    archive = { source = "hashicorp/archive", version = "~> 2.4" }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "ap-south-1" # Mumbai
}

variable "project" {
  type    = string
  default = "compute-choices" # prefix for every resource name
}

variable "office_cidr" {
  type        = string
  description = "Your public IP/32, allowed to reach the Windows app on port 80"
}

# Lab uses the default VPC to stay short; real landing zones use a dedicated VPC
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

output "api_url" {
  value = aws_apigatewayv2_api.api.api_endpoint
}

output "job_queue" {
  value = aws_batch_job_queue.nightly.name
}

output "job_definition" {
  value = aws_batch_job_definition.report.name
}

output "windows_asg" {
  value = aws_autoscaling_group.legacy.name
}

# Public API: Lambda (serverless functions) behind an HTTP API
data "archive_file" "api" {
  type        = "zip"
  source_file = "${path.module}/../src/api/handler.py"
  output_path = "${path.module}/build/api.zip"
}

resource "aws_iam_role" "lambda" {
  name = "${var.project}-api-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_logs" {
  role       = aws_iam_role.lambda.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "api" {
  function_name    = "${var.project}-api"
  role             = aws_iam_role.lambda.arn
  runtime          = "python3.13"
  handler          = "handler.lambda_handler"
  architectures    = ["arm64"] # Graviton: lower price per GB-second
  memory_size      = 512        # CPU is allocated in proportion to memory
  timeout          = 10         # API calls must be short; Lambda max is 900 s
  filename         = data.archive_file.api.output_path
  source_code_hash = data.archive_file.api.output_base64sha256

  environment {
    variables = { PROJECT = var.project }
  }
}

# Quick-create HTTP API: $default route and auto-deployed stage -> Lambda
resource "aws_apigatewayv2_api" "api" {
  name          = "${var.project}-http-api"
  protocol_type = "HTTP"
  target        = aws_lambda_function.api.arn
}

resource "aws_lambda_permission" "apigw" {
  statement_id  = "AllowHttpApiInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.api.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.api.execution_arn}/*/*"
}

"""Orders API on Lambda. Shows request routing and cold-start detection."""
import json
import os

PROJECT = os.environ.get("PROJECT", "compute-choices")

# Module-level code runs once per execution environment (the cold start).
# Put SDK clients and config loading here so warm calls reuse them.
_cold = True


def _response(status, body):
    return {
        "statusCode": status,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(body),
    }


def lambda_handler(event, context):
    global _cold
    was_cold, _cold = _cold, False  # True only on the first call in this environment

    path = event.get("rawPath", "/")  # HTTP API payload format 2.0

    if path == "/health":
        body = {"status": "ok", "project": PROJECT}
    elif path.startswith("/orders/"):
        order_id = path.rsplit("/", 1)[-1]
        # A real API would read from DynamoDB or RDS here
        body = {"orderId": order_id, "status": "CONFIRMED"}
    else:
        return _response(404, {"error": "not found", "path": path})

    body["coldStart"] = was_cold
    body["remainingMs"] = context.get_remaining_time_in_millis()
    return _response(200, body)

# Batch job: AWS Batch on Fargate Spot (serverless containers, pay per run)
resource "aws_security_group" "batch" {
  name   = "${var.project}-batch"
  vpc_id = data.aws_vpc.default.id

  egress { # outbound only: pull the image, write results
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "batch_exec" {
  name = "${var.project}-batch-exec"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "batch_exec" {
  role       = aws_iam_role.batch_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_batch_compute_environment" "spot" {
  type = "MANAGED" # uses the Batch service-linked role
  compute_resources {
    type               = "FARGATE_SPOT" # spare capacity at a discount; can be interrupted
    max_vcpus          = 16             # cost guardrail
    subnets            = data.aws_subnets.default.ids
    security_group_ids = [aws_security_group.batch.id]
  }
}

resource "aws_batch_job_queue" "nightly" {
  name     = "${var.project}-nightly"
  state    = "ENABLED"
  priority = 1
  compute_environment_order {
    order               = 1
    compute_environment = aws_batch_compute_environment.spot.arn
  }
}

resource "aws_batch_job_definition" "report" {
  name                  = "${var.project}-report"
  type                  = "container"
  platform_capabilities = ["FARGATE"]
  retry_strategy { attempts = 3 }           # re-run after a Spot interruption
  timeout { attempt_duration_seconds = 3600 } # longer than Lambda's 15-minute limit

  container_properties = jsonencode({
    image   = "public.ecr.aws/docker/library/python:3.13-slim"
    command = ["python", "-c", "import time; print('building nightly report'); time.sleep(60); print('done')"]
    resourceRequirements = [
      { type = "VCPU", value = "1" },
      { type = "MEMORY", value = "2048" }
    ]
    executionRoleArn             = aws_iam_role.batch_exec.arn
    networkConfiguration         = { assignPublicIp = "ENABLED" } # default VPC has no NAT
    fargatePlatformConfiguration = { platformVersion = "LATEST" }
  })
}

# Legacy Windows app: IaaS VM in an Auto Scaling group (full OS control)
data "aws_ssm_parameter" "win2022" { # latest AWS Windows AMI; use a golden AMI in production
  name = "/aws/service/ami-windows-latest/Windows_Server-2022-English-Full-Base"
}

resource "aws_iam_role" "windows" {
  name = "${var.project}-windows"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "ssm" { # admin via Session Manager / Fleet Manager, no RDP port
  role       = aws_iam_role.windows.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "windows" {
  name = "${var.project}-windows"
  role = aws_iam_role.windows.name
}

