terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" { region = var.region } # data residency: region is fixed here

resource "aws_s3_bucket" "logs" {
  bucket              = var.bucket_name
  object_lock_enabled = true # only possible at creation time
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration { status = "Enabled" } # Object Lock requires versioning
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" } # SSE-S3, no KMS request cost
  }
}

resource "aws_s3_bucket_object_lock_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    default_retention {
      mode = var.lock_mode      # WORM: GOVERNANCE for lab, COMPLIANCE for audit
      days = var.retention_days # 2557 days = 7 years including leap days
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket     = aws_s3_bucket.logs.id
  depends_on = [aws_s3_bucket_versioning.logs]

  rule {
    id     = "logs-tiering-7y"
    status = "Enabled"
    filter { prefix = "logs/" }
    transition {
      days          = var.days_to_glacier_ir
      storage_class = "GLACIER_IR"
    }
    transition {
      days          = var.days_to_deep_archive
      storage_class = "DEEP_ARCHIVE"
    }
    expiration { days = var.retention_days + 1 }            # adds delete marker after lock ends
    noncurrent_version_expiration { noncurrent_days = 1 } # then removes the old version
  }

  rule {
    id     = "housekeeping"
    status = "Enabled"
    filter {}
    abort_incomplete_multipart_upload { days_after_initiation = 7 }
    expiration { expired_object_delete_marker = true } # clean up leftover markers
  }
}

output "bucket_name" { value = aws_s3_bucket.logs.id }

variable "region" {
  description = "Region that satisfies data residency, e.g. ap-south-1 (Mumbai)"
  type        = string
  default     = "ap-south-1"
}

variable "bucket_name" {
  description = "Globally unique S3 bucket name"
  type        = string
}

variable "lock_mode" {
  description = "Object Lock mode. Use COMPLIANCE for real regulatory retention"
  type        = string
  default     = "GOVERNANCE"
  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.lock_mode)
    error_message = "lock_mode must be GOVERNANCE or COMPLIANCE."
  }
}

variable "retention_days" {
  description = "Retention rule: 7 years"
  type        = number
  default     = 2557
}

variable "days_to_glacier_ir" {
  description = "Age at which logs leave STANDARD"
  type        = number
  default     = 30
}

variable "days_to_deep_archive" {
  description = "Age at which logs move to DEEP_ARCHIVE"
  type        = number
  default     = 180
  validation {
    # Glacier IR has a 90-day minimum storage charge; leaving earlier costs extra
    condition     = var.days_to_deep_archive - var.days_to_glacier_ir >= 90
    error_message = "Keep objects in GLACIER_IR for at least 90 days."
  }
}

