terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  alias  = "primary"
  region = "ap-south-1" # Mumbai
}

provider "aws" {
  alias  = "dr"
  region = "ap-south-2" # Hyderabad
}

variable "db_password" {
  type      = string
  sensitive = true
}
variable "primary_db_subnet_group" { type = string }
variable "dr_db_subnet_group" { type = string }
variable "dr_launch_template_id" { type = string }
variable "dr_subnet_ids" { type = list(string) }
variable "dr_target_group_arn" { type = string }

# Primary DB. Multi-AZ handles a zone failure without a DR event.
resource "aws_db_instance" "primary" {
  provider                = aws.primary
  identifier              = "shop-db-primary"
  engine                  = "postgres"
  engine_version          = "16"
  instance_class          = "db.t4g.medium"
  allocated_storage       = 50
  db_name                 = "shop"
  username                = "shopadmin"
  password                = var.db_password
  multi_az                = true
  storage_encrypted       = true
  backup_retention_period = 7 # required for read replicas; also gives PITR
  db_subnet_group_name    = var.primary_db_subnet_group
  skip_final_snapshot     = true # lab only
}

# An encrypted cross-region replica needs a KMS key in the DR region
resource "aws_kms_key" "dr" {
  provider    = aws.dr
  description = "shop DR replica key"
}

# Pilot light data layer: async replica, lag is usually seconds (RPO)
resource "aws_db_instance" "replica" {
  provider             = aws.dr
  identifier           = "shop-db-dr"
  replicate_source_db  = aws_db_instance.primary.arn # cross-region needs the ARN
  instance_class       = "db.t4g.medium"
  kms_key_id           = aws_kms_key.dr.arn
  storage_encrypted    = true
  db_subnet_group_name = var.dr_db_subnet_group
  skip_final_snapshot  = true
}

# Pilot light app tier: defined but scaled to zero until failover
resource "aws_autoscaling_group" "dr_app" {
  provider            = aws.dr
  name                = "shop-app-dr"
  min_size            = 0
  max_size            = 6
  desired_capacity    = 0
  vpc_zone_identifier = var.dr_subnet_ids
  target_group_arns   = [var.dr_target_group_arn]
  launch_template {
    id      = var.dr_launch_template_id
    version = "$Latest"
  }
  lifecycle { ignore_changes = [desired_capacity] } # failover script scales it
}

variable "zone_id" { type = string }
variable "domain" { type = string } # e.g. shop.example.in
variable "primary_alb_dns" { type = string }
variable "primary_alb_zone_id" { type = string }
variable "dr_alb_dns" { type = string }
variable "dr_alb_zone_id" { type = string }

# Probes the primary app; /health returns 200 only if the DB is writable
resource "aws_route53_health_check" "primary" {
  provider          = aws.primary
  fqdn              = var.primary_alb_dns
  port              = 443
  type              = "HTTPS"
  resource_path     = "/health"
  failure_threshold = 3 # 3 failed checks before marked unhealthy
  request_interval  = 30
  tags              = { Name = "shop-primary-health" }
}

resource "aws_route53_record" "primary" {
  provider        = aws.primary
  zone_id         = var.zone_id
  name            = var.domain
  type            = "A"
  set_identifier  = "primary"
  health_check_id = aws_route53_health_check.primary.id
  failover_routing_policy { type = "PRIMARY" }
  alias {
    name                   = var.primary_alb_dns
    zone_id                = var.primary_alb_zone_id
    evaluate_target_health = true
  }
}

# Served only when PRIMARY is unhealthy
resource "aws_route53_record" "secondary" {
  provider       = aws.primary
  zone_id        = var.zone_id
  name           = var.domain
  type           = "A"
  set_identifier = "dr"
  failover_routing_policy { type = "SECONDARY" }
  alias {
    name                   = var.dr_alb_dns
    zone_id                = var.dr_alb_zone_id
    evaluate_target_health = true
  }
}

# Guards the RPO: alert if replica lag goes above 5 min (budget is 15)
resource "aws_cloudwatch_metric_alarm" "replica_lag" {
  provider            = aws.dr
  alarm_name          = "shop-db-dr-replica-lag"
  namespace           = "AWS/RDS"
  metric_name         = "ReplicaLag"
  dimensions          = { DBInstanceIdentifier = aws_db_instance.replica.identifier }
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 300
  comparison_operator = "GreaterThanThreshold"
}

output "replica_id" { value = aws_db_instance.replica.identifier }
output "dr_asg_name" { value = aws_autoscaling_group.dr_app.name }
output "health_check_id" { value = aws_route53_health_check.primary.id }

