terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40"
    }
  }
}

provider "aws" {
  region = var.region
  default_tags {
    tags = { Project = var.prefix, Step = "08-security" } # tags help FinOps and audits
  }
}

variable "region" {
  type    = string
  default = "ap-south-1"
}

variable "prefix" {
  type    = string
  default = "mc-lz"
}

variable "alb_arn" {
  description = "ARN of an existing ALB to protect with WAF. Leave empty to skip."
  type        = string
  default     = ""
}

variable "object_lock_mode" {
  description = "GOVERNANCE for labs, COMPLIANCE for production"
  type        = string
  default     = "GOVERNANCE"
}

variable "log_retention_days" {
  type    = number
  default = 365
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  trail_name = "${var.prefix}-trail"
  # Built by hand so the KMS key policy can reference the trail before it exists
  trail_arn = "arn:aws:cloudtrail:${var.region}:${local.account_id}:trail/${local.trail_name}"
}

output "data_key_arn" {
  value = aws_kms_key.data.arn
}

output "log_archive_bucket" {
  value = aws_s3_bucket.log_archive.id
}

output "orders_table" {
  value = aws_dynamodb_table.orders.name
}

output "web_acl_arn" {
  value = aws_wafv2_web_acl.edge.arn
}

# Data CMK: KMS wraps per-object data keys (envelope encryption).
# The default key policy trusts this account's IAM, so access is controlled by IAM.
resource "aws_kms_key" "data" {
  description             = "${var.prefix} application data CMK"
  enable_key_rotation     = true # automatic yearly rotation
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "data" {
  name          = "alias/${var.prefix}-data"
  target_key_id = aws_kms_key.data.key_id
}

# Separate logs CMK: data admins and log admins are kept apart (separation of duties)
resource "aws_kms_key" "logs" {
  description             = "${var.prefix} audit and security logs CMK"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "AccountAdmin", Effect = "Allow", Principal = { AWS = "arn:aws:iam::${local.account_id}:root" }, Action = "kms:*", Resource = "*" },
      { Sid = "CloudTrail", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" },
        Action = ["kms:GenerateDataKey*", "kms:DescribeKey"], Resource = "*",
      Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } },
      { Sid = "ConfigDelivery", Effect = "Allow", Principal = { Service = "config.amazonaws.com" },
        Action = ["kms:Decrypt", "kms:GenerateDataKey"], Resource = "*",
      Condition = { StringEquals = { "aws:SourceAccount" = local.account_id } } },
      { Sid = "CloudWatchLogs", Effect = "Allow", Principal = { Service = "logs.${var.region}.amazonaws.com" },
        Action = ["kms:Encrypt*", "kms:Decrypt*", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:Describe*"], Resource = "*",
      Condition = { ArnLike = { "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${var.region}:${local.account_id}:log-group:*" } } }
    ]
  })
}

resource "aws_s3_bucket" "app" {
  bucket = "${var.prefix}-app-data-${local.account_id}"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app" {
  bucket = aws_s3_bucket.app.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms" # SSE-KMS with our CMK, not the AWS managed key
      kms_master_key_id = aws_kms_key.data.arn
    }
    bucket_key_enabled = true # fewer KMS requests, lower cost
  }
}

resource "aws_s3_bucket_public_access_block" "app" {
  bucket                  = aws_s3_bucket.app.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "app_tls_only" {
  bucket = aws_s3_bucket.app.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{ Sid = "DenyNonTLS", Effect = "Deny", Principal = "*", Action = "s3:*", # encryption in transit
      Resource = [aws_s3_bucket.app.arn, "${aws_s3_bucket.app.arn}/*"],
    Condition = { Bool = { "aws:SecureTransport" = "false" } } }]
  })
}

resource "aws_dynamodb_table" "orders" {
  name         = "${var.prefix}-orders"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "order_id"
  attribute {
    name = "order_id"
    type = "S"
  }
  server_side_encryption {
    enabled     = true # customer managed key instead of the AWS owned default
    kms_key_arn = aws_kms_key.data.arn
  }
}

# Central audit log archive. In production, put this in a separate Log Archive account.
resource "aws_s3_bucket" "log_archive" {
  bucket              = "${var.prefix}-log-archive-${local.account_id}"
  object_lock_enabled = true # WORM storage; must be set when the bucket is created
}

resource "aws_s3_bucket_versioning" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_object_lock_configuration" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  rule {
    default_retention {
      mode = var.object_lock_mode # COMPLIANCE: nobody can delete before expiry
      days = var.log_retention_days
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_archive" {
  bucket                  = aws_s3_bucket.log_archive.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "log_archive" {
  bucket = aws_s3_bucket.log_archive.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      { Sid = "DenyNonTLS", Effect = "Deny", Principal = "*", Action = "s3:*", Resource = [aws_s3_bucket.log_archive.arn, "${aws_s3_bucket.log_archive.arn}/*"], Condition = { Bool = { "aws:SecureTransport" = "false" } } },
      { Sid = "CloudTrailAclCheck", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:GetBucketAcl", Resource = aws_s3_bucket.log_archive.arn, Condition = { StringEquals = { "aws:SourceArn" = local.trail_arn } } },
      { Sid = "CloudTrailWrite", Effect = "Allow", Principal = { Service = "cloudtrail.amazonaws.com" }, Action = "s3:PutObject", Resource = "${aws_s3_bucket.log_archive.arn}/AWSLogs/${local.account_id}/*",
      Condition = { StringEquals = { "s3:x-amz-acl" = "bucket-owner-full-control", "aws:SourceArn" = local.trail_arn } } },
      { Sid = "ConfigCheck", Effect = "Allow", Principal = { Service = "config.amazonaws.com" }, Action = ["s3:GetBucketAcl", "s3:ListBucket"], Resource = aws_s3_bucket.log_archive.arn, Condition = { StringEquals = { "aws:SourceAccount" = local.account_id } } },
      { Sid = "ConfigWrite", Effect = "Allow", Principal = { Service = "config.amazonaws.com" }, Action = "s3:PutObject", Resource = "${aws_s3_bucket.log_archive.arn}/config/AWSLogs/${local.account_id}/Config/*",
      Condition = { StringEquals = { "s3:x-amz-acl" = "bucket-owner-full-control", "aws:SourceAccount" = local.account_id } } }
    ]
  })
}

# Records every management (admin) API call in every Region
resource "aws_cloudtrail" "main" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.log_archive.id
  is_multi_region_trail         = true
  include_global_service_events = true # IAM, STS and other global services
  enable_log_file_validation    = true # digest files detect edited logs
  kms_key_id                    = aws_kms_key.logs.arn
  depends_on                    = [aws_s3_bucket_policy.log_archive]
}

# Layer 7 protection for a public ALB. Shield Standard already covers L3/L4 DDoS.
resource "aws_wafv2_web_acl" "edge" {
  name  = "${var.prefix}-edge-acl"
  scope = "REGIONAL" # use CLOUDFRONT (in us-east-1) for CloudFront distributions
  default_action {
    allow {}
  }

  rule {
    name     = "aws-common-rules" # OWASP-style protections managed by AWS
    priority = 1
    override_action {
      none {}
    }
    statement {
      managed_rule_group_statement {
        name        = "AWSManagedRulesCommonRuleSet"
        vendor_name = "AWS"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "common-rules"
      sampled_requests_enabled   = true
    }
  }

  rule {
    name     = "rate-limit-per-ip" # slows brute force and small HTTP floods
    priority = 2
    action {
      block {}
    }
    statement {
      rate_based_statement {
        limit              = 1000 # requests per IP in the evaluation window
        aggregate_key_type = "IP"
      }
    }
    visibility_config {
      cloudwatch_metrics_enabled = true
      metric_name                = "rate-limit"
      sampled_requests_enabled   = true
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "${var.prefix}-edge-acl"
    sampled_requests_enabled   = true
  }
}

resource "aws_wafv2_web_acl_association" "alb" {
  count        = var.alb_arn == "" ? 0 : 1 # attach only when an ALB is given
  resource_arn = var.alb_arn
  web_acl_arn  = aws_wafv2_web_acl.edge.arn
}

resource "aws_cloudwatch_log_group" "waf" {
  name              = "aws-waf-logs-${var.prefix}" # WAF requires the aws-waf-logs- prefix
  retention_in_days = 90
  kms_key_id        = aws_kms_key.logs.arn
}

resource "aws_wafv2_web_acl_logging_configuration" "edge" {
  resource_arn            = aws_wafv2_web_acl.edge.arn
  log_destination_configs = [aws_cloudwatch_log_group.waf.arn]
}

# Threat detection: GuardDuty analyses CloudTrail, VPC Flow Logs and DNS logs
resource "aws_guardduty_detector" "main" {
  enable = true
}

# AWS Config records resource settings. Security Hub CSPM controls depend on it.
# Remove these Config resources if Control Tower already manages Config here.
resource "aws_iam_service_linked_role" "config" {
  aws_service_name = "config.amazonaws.com"
}

resource "aws_config_configuration_recorder" "main" {
  name     = "${var.prefix}-recorder"
  role_arn = aws_iam_service_linked_role.config.arn
  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = "${var.prefix}-delivery"
  s3_bucket_name = aws_s3_bucket.log_archive.id # same central, locked archive
  s3_key_prefix  = "config"
  s3_kms_key_arn = aws_kms_key.logs.arn
  depends_on     = [aws_config_configuration_recorder.main, aws_s3_bucket_policy.log_archive]
