# Inputs and outputs of the network module.
# Keep the interface small: callers pass only what changes per environment.

variable "name" {
  description = "Name prefix, for example mc-dev"
  type        = string
}

variable "cidr" {
  description = "VPC CIDR block, must not overlap other environments"
  type        = string

  validation {
    condition     = can(cidrhost(var.cidr, 0)) # fail early on a bad CIDR
    error_message = "cidr must be a valid IPv4 CIDR block."
  }
}

variable "azs" {
  description = "Availability Zones to spread subnets across"
  type        = list(string)

  validation {
    condition     = length(var.azs) >= 2 # resilience: at least two AZs
    error_message = "Use at least two Availability Zones."
  }
}

variable "tags" {
  description = "Extra tags merged onto every resource"
  type        = map(string)
  default     = {}
}

output "vpc_id" {
  value = aws_vpc.this.id
}

output "public_subnet_ids" {
  value = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  value = aws_subnet.private[*].id
}

# Reusable landing-zone network: VPC, public and private subnets per AZ.

resource "aws_vpc" "this" {
  cidr_block           = var.cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(var.tags, { Name = var.name })
}

# One /24 public subnet per AZ: 10.x.0.0/24, 10.x.1.0/24 ...
resource "aws_subnet" "public" {
  count             = length(var.azs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.cidr, 8, count.index)
  availability_zone = var.azs[count.index]
  tags              = merge(var.tags, { Name = "${var.name}-public-${var.azs[count.index]}", tier = "public" })
}

# Private subnets start at offset 100 so ranges never collide.
resource "aws_subnet" "private" {
  count             = length(var.azs)
  vpc_id            = aws_vpc.this.id
  cidr_block        = cidrsubnet(var.cidr, 8, count.index + 100)
  availability_zone = var.azs[count.index]
  tags              = merge(var.tags, { Name = "${var.name}-private-${var.azs[count.index]}", tier = "private" })
}

resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags   = merge(var.tags, { Name = "${var.name}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id
  tags   = merge(var.tags, { Name = "${var.name}-public-rt" })

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }
}

resource "aws_route_table_association" "public" {
  count          = length(var.azs)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Take control of the default security group and remove all its rules
# (a common security baseline finding).
resource "aws_default_security_group" "this" {
  vpc_id = aws_vpc.this.id
  tags   = merge(var.tags, { Name = "${var.name}-default-locked" })
}

# The dev environment: state, provider and module composition.

terraform {
  required_version = ">= 1.10" # needed for use_lockfile in the S3 backend

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0" # pin the major version; the lock file pins the exact one
    }
  }

  # Remote state: one key per environment, encrypted, locked with an S3 lock file.
  backend "s3" {
    bucket       = "mc-tfstate-123456789012"
    key          = "landing-zone/dev/terraform.tfstate"
    region       = "ap-south-1"
    encrypt      = true
    use_lockfile = true
  }
}

locals {
  environment = "dev"
}

provider "aws" {
  region = "ap-south-1"

  # FinOps: every resource gets these tags without repeating them.
  default_tags {
    tags = {
      environment   = local.environment
      owner         = "platform-team"
      "cost-centre" = "cc-1001"
      "managed-by"  = "terraform"
    }
  }
}

module "network" {
  source = "../../modules/network" # in a real org, pin a git tag or registry version

  name = "mc-${local.environment}"
  cidr = "10.10.0.0/16"
  azs  = ["ap-south-1a", "ap-south-1b"]
}

output "vpc_id" {
  value = module.network.vpc_id
}

output "private_subnet_ids" {
  value = module.network.private_subnet_ids
}

