terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" {
  region = "ap-south-1"
  default_tags { tags = { CostCenter = "platform", Env = "prod" } } # tag everything by default
}

variable "alert_email" { type = string }
variable "logs_bucket" { type = string }
variable "dev_instance_ids" { type = list(string) }

# Tags appear in billing only after you activate them as cost allocation tags
resource "aws_ce_cost_allocation_tag" "cost_center" {
  tag_key = "CostCenter"
  status  = "Active"
}

resource "aws_budgets_budget" "payments" {
  name         = "payments-monthly"
  budget_type  = "COST"
  limit_amount = "5000"
  limit_unit   = "USD"
  time_unit    = "MONTHLY"
  cost_filter {
    name   = "TagKeyValue"
    values = ["user:CostCenter$payments"] # scope the budget to one team
  }
  notification { # early warning on the forecast
    comparison_operator        = "GREATER_THAN"
    threshold                  = 80
    threshold_type             = "PERCENTAGE"
    notification_type          = "FORECASTED"
    subscriber_email_addresses = [var.alert_email]
  }
  notification { # actual spend has passed the limit
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = [var.alert_email]
  }
}

# Cost Anomaly Detection: ML-based spike detection per AWS service
resource "aws_ce_anomaly_monitor" "services" {
  name              = "per-service-monitor"
  monitor_type      = "DIMENSIONAL"
  monitor_dimension = "SERVICE"
}

resource "aws_ce_anomaly_subscription" "email" {
  name             = "anomaly-daily-email"
  frequency        = "DAILY" # email subscribers need DAILY or WEEKLY
  monitor_arn_list = [aws_ce_anomaly_monitor.services.arn]
  subscriber {
    type    = "EMAIL"
    address = var.alert_email
  }
  threshold_expression {
    dimension {
      key           = "ANOMALY_TOTAL_IMPACT_ABSOLUTE"
      match_options = ["GREATER_THAN_OR_EQUAL"]
      values        = ["100"] # alert only when the impact is USD 100 or more
    }
  }
}

# Storage tiering: logs move to cheaper classes as they age, then expire
resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = var.logs_bucket
  rule {
    id     = "tier-and-expire-logs"
    status = "Enabled"
    filter {}
    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }
    transition {
      days          = 90
      storage_class = "GLACIER_IR"
    }
    expiration { days = 365 }
  }
}

# Switch non-production off after hours: stop dev EC2 at 20:00 IST, Mon-Fri.
# A matching start schedule (for example 08:00) gives about 60 hours on per week.

resource "aws_iam_role" "scheduler" {
  name = "dev-stop-scheduler"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "scheduler.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "stop_ec2" {
  role = aws_iam_role.scheduler.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = ["ec2:StopInstances"]
      Resource = "*"
      # Least privilege: only instances tagged Env=dev can be stopped
      Condition = { StringEquals = { "aws:ResourceTag/Env" = "dev" } }
    }]
  })
}

resource "aws_scheduler_schedule" "stop_dev" {
  name                         = "stop-dev-evening"
  schedule_expression          = "cron(0 20 ? * MON-FRI *)"
  schedule_expression_timezone = "Asia/Kolkata"
  flexible_time_window { mode = "OFF" }
  target {
    # Universal target: calls the EC2 StopInstances API directly, so no Lambda is needed
    arn      = "arn:aws:scheduler:::aws-sdk:ec2:stopInstances"
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ InstanceIds = var.dev_instance_ids })
  }
}

