"""Checkpoint: every server has one of the 7 Rs, a reason and a safe wave."""
import csv
import sys
from collections import Counter, defaultdict
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
SEVEN_RS = {"retire", "retain", "rehost", "relocate", "replatform", "repurchase", "refactor"}


def load():
    with open(ROOT / "inventory" / "servers.csv", newline="") as f:
        servers = {row["id"]: row for row in csv.DictReader(f)}
    with open(ROOT / "plan" / "waves.yaml") as f:
        waves = {w["number"]: w for w in yaml.safe_load(f)["waves"]}
    return servers, waves


def validate(servers, waves):
    errors = []
    for sid, s in servers.items():
        r, wave = s["r"].strip().lower(), int(s["wave"])
        if r not in SEVEN_RS:
            errors.append(f"{sid}: '{r}' is not one of the 7 Rs")
        if len(s["reason"].strip()) < 10:  # the checkpoint: a real reason
            errors.append(f"{sid}: reason is missing or too short")
        if r == "retain" and wave != 0:
            errors.append(f"{sid}: retained servers stay on-prem (wave 0)")
        if r != "retain" and wave not in waves and not (r == "retire" and wave == 0):
            errors.append(f"{sid}: wave {wave} has no runbook in waves.yaml")
        for dep in filter(None, s["depends_on"].split(";")):
            d = servers.get(dep)
            if d is None:
                errors.append(f"{sid}: unknown dependency {dep}")
            elif d["r"] == "retire":
                errors.append(f"{sid}: depends on {dep}, which is being retired")
            elif d["r"] != "retain" and int(d["wave"]) > wave:
                # Moving before a dependency means extra latency over the hybrid link
                errors.append(f"{sid}: wave {wave} but depends on {dep} in wave {d['wave']}")
    for n, w in waves.items():
        if not w.get("rollback", {}).get("steps"):
            errors.append(f"wave {n}: no rollback steps")
    return errors


def report(servers, waves):
    by_wave = defaultdict(list)
    for sid, s in servers.items():
        by_wave[int(s["wave"])].append(f"{sid} {s['hostname']} [{s['r']}]")
    for n in sorted(by_wave):
        title = waves[n]["name"] if n in waves else "Not migrated (retain / retire)"
        rb = waves[n]["rollback"]["time_limit_minutes"] if n in waves else "-"
        print(f"\nWave {n}: {title} | rollback limit: {rb} min")
        for line in by_wave[n]:
            print("  " + line)
    print("\nServers per R:", dict(Counter(s["r"] for s in servers.values())))
    print(f"Total servers: {len(servers)}")


if __name__ == "__main__":
    servers, waves = load()
    problems = validate(servers, waves)
    report(servers, waves)
    if problems:
        print("\nPLAN FAILED:\n  " + "\n  ".join(problems))
        sys.exit(1)
    print("\nPLAN OK: every server has an R, a reason and a safe wave.")

# Wave 3: strangler-fig. The ALB sends everything to the monolith except the routes we have rebuilt.
terraform {
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 5.0" }
  }
}

provider "aws" { region = var.region }

variable "region" {
  type    = string
  default = "ap-south-1"
}
variable "vpc_id" { type = string }
variable "public_subnet_ids" { type = list(string) }
variable "monolith_ips" {
  type        = list(string) # private IPs of shop-mono01/02, reachable over VPN or Direct Connect
  description = "Monolith IP targets (private ranges only)"
}
variable "orders_weight" {
  type    = number
  default = 0 # rollback = set this back to 0
  validation {
    condition     = var.orders_weight >= 0 && var.orders_weight <= 100
    error_message = "orders_weight must be between 0 and 100."
  }
}

resource "aws_security_group" "alb" {
  name   = "shop-alb"
  vpc_id = var.vpc_id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "shop" {
  name               = "shop-alb"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = var.public_subnet_ids
}

resource "aws_lb_target_group" "monolith" {
  name        = "shop-monolith"
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip" # IP targets allow servers outside the VPC (on-prem)
  vpc_id      = var.vpc_id
  health_check { path = "/health" }
}

resource "aws_lb_target_group_attachment" "monolith" {
  count             = length(var.monolith_ips)
  target_group_arn  = aws_lb_target_group.monolith.arn
  target_id         = var.monolith_ips[count.index]
  port              = 8080
  availability_zone = "all" # required for IPs outside the VPC
}

resource "aws_lb_target_group" "orders" {
  name        = "shop-orders-svc" # the new ECS orders service registers its tasks here
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = var.vpc_id
  health_check { path = "/health" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.shop.arn
  port              = 80 # use 443 with an ACM certificate in production
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.monolith.arn
  }
}

resource "aws_lb_listener_rule" "orders" {
  listener_arn = aws_lb_listener.http.arn
  priority     = 10
  action {
    type = "forward"
    forward { # weighted canary: shift orders traffic step by step
      target_group {
        arn    = aws_lb_target_group.orders.arn
        weight = var.orders_weight
      }
      target_group {
        arn    = aws_lb_target_group.monolith.arn
        weight = 100 - var.orders_weight
      }
    }
  }
  condition {
    path_pattern { values = ["/api/orders*"] }
  }
}

output "alb_dns_name" { value = aws_lb.shop.dns_name }

