files.code:
terraform {
  required_version = ">= 1.6"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

variable "primary_region" { default = "ap-south-1" } # Mumbai
variable "dr_region"      { default = "ap-south-2" } # Hyderabad
variable "zone_id"        { type = string }          # Route 53 hosted zone
variable "app_fqdn"       { type = string }          # e.g. orders.kirana.example
variable "primary_alb_dns" { type = string }
variable "primary_alb_zone_id" { type = string }
variable "dr_alb_dns"     { type = string }
variable "dr_alb_zone_id" { type = string }

provider "aws" { region = var.primary_region }

# DynamoDB global table: write in Mumbai, replica in Hyderabad (RPO driver)
resource "aws_dynamodb_table" "orders" {
  name             = "orders"
  billing_mode     = "PAY_PER_REQUEST" # on-demand for spiky traffic
  hash_key         = "order_id"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES" # required for replicas
  attribute {
    name = "order_id"
    type = "S"
  }
  replica { region_name = var.dr_region }
  point_in_time_recovery { enabled = true } # protects against bad writes
}

# Health check on the primary ALB decides when Route 53 fails over
resource "aws_route53_health_check" "primary" {
  fqdn              = var.primary_alb_dns
  port              = 443
  type              = "HTTPS"
  resource_path     = "/health"
  failure_threshold = 3
  request_interval  = 30
}

resource "aws_route53_record" "primary" {
  zone_id         = var.zone_id
  name            = var.app_fqdn
  type            = "A"
  set_identifier  = "primary"
  health_check_id = aws_route53_health_check.primary.id
  failover_routing_policy { type = "PRIMARY" }
  alias {
    name                   = var.primary_alb_dns
    zone_id                = var.primary_alb_zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "secondary" {
  zone_id        = var.zone_id
  name           = var.app_fqdn
  type           = "A"
  set_identifier = "secondary"
  failover_routing_policy { type = "SECONDARY" } # warm standby target
  alias {
    name                   = var.dr_alb_dns
    zone_id                = var.dr_alb_zone_id
    evaluate_target_health = true
  }
}

# Deployed in the 'network' account; shared to workload accounts via RAM
variable "onprem_public_ip"   { type = string }       # Pune firewall public IP
variable "network_vpc_id"     { type = string }
variable "network_subnet_ids" { type = list(string) } # one subnet per AZ
variable "org_arn"            { type = string }       # AWS Organization ARN

resource "aws_ec2_transit_gateway" "hub" {
  description                     = "kirana-hub"
  amazon_side_asn                 = 64512
  auto_accept_shared_attachments  = "enable" # workload VPCs attach without manual approval
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"
}

resource "aws_ec2_transit_gateway_vpc_attachment" "network" {
  transit_gateway_id = aws_ec2_transit_gateway.hub.id
  vpc_id             = var.network_vpc_id
  subnet_ids         = var.network_subnet_ids
}

resource "aws_customer_gateway" "pune" {
  bgp_asn    = 65000
  ip_address = var.onprem_public_ip
  type       = "ipsec.1"
}

# Two IPsec tunnels with BGP; replace or back up with Direct Connect when traffic grows
resource "aws_vpn_connection" "pune" {
  customer_gateway_id = aws_customer_gateway.pune.id
  transit_gateway_id  = aws_ec2_transit_gateway.hub.id
  type                = "ipsec.1"
  static_routes_only  = false
}

# Multi-account: share the TGW with the whole Organization
resource "aws_ram_resource_share" "tgw" {
  name                      = "kirana-tgw-share"
  allow_external_principals = false # only accounts inside the org
}

resource "aws_ram_resource_association" "tgw" {
  resource_arn       = aws_ec2_transit_gateway.hub.arn
  resource_share_arn = aws_ram_resource_share.tgw.arn
}

resource "aws_ram_principal_association" "org" {
  principal          = var.org_arn
  resource_share_arn = aws_ram_resource_share.tgw.arn
}

output "transit_gateway_id" { value = aws_ec2_transit_gateway.hub.id }
output "vpn_connection_id"  { value = aws_vpn_connection.pune.id }

